import openpyxl

wb = openpyxl.load_workbook('./materials/FinancialStatementFY26Q4.xlsx', data_only=False)
print("Sheet names:", wb.sheetnames)

for sheet_name in wb.sheetnames:
    ws = wb[sheet_name]
    print(f"\n=== Sheet: {sheet_name} ===")
    print(f"Dimensions: {ws.dimensions}")
    print(f"Max row: {ws.max_row}, Max col: {ws.max_column}")
    # Print first 50 rows
    for row in ws.iter_rows(min_row=1, max_row=min(50, ws.max_row), values_only=False):
        row_data = []
        for cell in row:
            if cell.value is not None:
                row_data.append(f"{cell.coordinate}={cell.value}")
        if row_data:
            print("  ", "; ".join(row_data))
